import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static long w;

    // Round |total|/w to six decimals exactly: split into quotient and remainder to avoid overflow.
    static void rounded(StringBuilder sb, long total) {
        long t = Math.abs(total), q = t / w, r = t % w;
        long scaled = q * 1000000 + (2 * r * 1000000 + w) / (2 * w);
        if (total < 0 && scaled != 0) sb.append('-');
        sb.append(scaled / 1000000).append('.');
        String frac = Long.toString(scaled % 1000000);
        for (int i = frac.length(); i < 6; i++) sb.append('0');
        sb.append(frac);
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        w = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        if (w > n) {
            System.out.println(0);
            return;
        }
        int wi = (int) w;
        long total = 0;
        for (int i = 0; i < wi; i++) total += a[i];
        StringBuilder sb = new StringBuilder();
        sb.append(n - wi + 1).append('\n');
        rounded(sb, total);
        for (int i = wi; i < n; i++) {
            total += a[i] - a[i - wi];
            sb.append(' ');
            rounded(sb, total);
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

