import (
	"fmt"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

var w int64

// Round |total|/w to six decimals exactly: split into quotient and remainder to avoid overflow.
func rounded(out []byte, total int64) []byte {
	t := total
	if t < 0 {
		t = -t
	}
	q, r := t/w, t%w
	scaled := q*1000000 + (2*r*1000000+w)/(2*w)
	if total < 0 && scaled != 0 {
		out = append(out, '-')
	}
	return fmt.Appendf(out, "%d.%06d", scaled/1000000, scaled%1000000)
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	w = nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	if w > int64(n) {
		fmt.Println(0)
		return
	}
	wi := int(w)
	var total int64
	for i := 0; i < wi; i++ {
		total += a[i]
	}
	out := strconv.AppendInt(nil, int64(n-wi+1), 10)
	out = append(out, '\n')
	out = rounded(out, total)
	for i := wi; i < n; i++ {
		total += a[i] - a[i-wi]
		out = append(out, ' ')
		out = rounded(out, total)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
